import { Accessor, Component, createMemo, createSignal, For, Show } from "solid-js";

import { ComponentID } from "#core/ui/utilities/utilities-component-id.js";
import { CollapsibleContainer } from "#core/ui-next/components/collapsible-container.jsx";
import { Icon } from "#core/ui-next/components/icon.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { ScrollArea } from "#core/ui-next/components/scroll-area.jsx";
import { SpatialSlot } from "#core/ui-next/components/slot.jsx";
import { createLayoutComplete } from "#core/ui-next/utilities/solid-utilities.js";

import { GamepadTrayItem, GamepadTrayItemProvider } from "#base/ui-next/components/gamepad-tray-item-provider.jsx";
import { CommerceScreenBaseTabContent } from "#base/ui-next/screens/commerce/commerce-screen-base-tab-content.jsx";
import { TreasureTabData, useCommerceScreenContext } from "#base/ui-next/screens/commerce/commerce-screen-model.js";
import { TreasureConvoyCard } from "#base/ui-next/screens/commerce/treasure-convoy-card.jsx";

//#region TREASURE RESOURCES
export const TreasureResourceContainer: Component<TreasureTabData> = (props) => {
	const model = useCommerceScreenContext();

	const layoutComplete = createLayoutComplete();

	const [focusedConvoyCard, setFocusedConvoyCard] = createSignal<ComponentID | undefined>();

	const firstVisibleSectionIndex = createMemo(() => {
		let visibleSectionIndex = -1;
		props.sections.forEach((section, index) => {
			if (visibleSectionIndex > -1) {
				return;
			}
			if (section.fleets.length > 0) {
				visibleSectionIndex = index;
			}
		});
		return visibleSectionIndex;
	});
	const shouldAutoFocusConvoyCard = (convoyCityID: ComponentID, sectionIndex: number, fleetIndex: number) => {
		if (!layoutComplete()) {
			return false;
		}

		if (focusedConvoyCard() === undefined) {
			return sectionIndex === firstVisibleSectionIndex() && fleetIndex === 0;
		}

		return ComponentID.isMatch(focusedConvoyCard()!, convoyCityID);
	};

	const gamepadTrayItems: Accessor<GamepadTrayItem[]> = createMemo(() => {
		if (model.selectedTreasureConvoyId()) {
			const selectedCity = Cities.get(model.selectedTreasureConvoyId()!);
			if (selectedCity) {
				const deselectRouteLabel = Locale.compose(
					"LOC_COMMERCE_GAMEPAD_STOP_VIEWING_CONTAINER_HINT",
					Locale.compose(selectedCity.name),
				);
				return [
					{
						hotkeyAction: "cancel",
						name: "cancel-treasure-convoy-edit",
						navTrayText: deselectRouteLabel,
						onActivate: () => model.setSelectedTreasureConvoyId(),
					},
				] as GamepadTrayItem[];
			}
			console.warn(
				"commerce-screen-treasure-tab.tsx: When getting gamepadTrayItems, couldn't find city with ID",
				model.selectedTreasureConvoyId(),
			);
		} else {
			if (focusedConvoyCard()) {
				const focusedCity = Cities.get(focusedConvoyCard()!);
				if (focusedCity) {
					const selectRouteLabel = Locale.compose(
						"LOC_COMMERCE_GAMEPAD_VIEW_CONTAINER_HINT",
						Locale.compose(focusedCity.name),
					);
					return [
						{
							hotkeyAction: "accept",
							name: "treasure-convoy-edit",
							navTrayText: selectRouteLabel,
							// activate handled by activatable in treasure-convoy-card.tsx
						},
					] as GamepadTrayItem[];
				}
			}
		}
		return [];
	});
	return (
		<SpatialSlot
			name="Commerce-Screen-Treasure-Tab"
			class="flex-auto"
		>
			<CommerceScreenBaseTabContent
				title="LOC_COMMERCE_TREASURE_FLEETS_TITLE"
				description="LOC_COMMERCE_TREASURE_EMPTY_DESCRIPTION"
			>
				<GamepadTrayItemProvider
					class="flex-auto"
					name="treasure-convoy-gamepad-items"
					items={gamepadTrayItems}
				>
					<ScrollArea class="flex-auto">
						<div class="flex flex-row flex-wrap flex-auto relative">
							<For each={props.sections}>
								{(section, index) => (
									<CollapsibleContainer
										{...section.collapsibleContainerData}
										class="w-full"
										headerClass="font-title fxs-header"
										disableFocus={model.selectedTreasureConvoyId() !== undefined}
									>
										<Show
											when={section.fleets.length == 0 && section.emptyTitle != undefined}
											fallback={
												<div class="flex flex-row flex-wrap flex-auto relative mt-6">
													<For each={section.fleets}>
														{(fleet, subIndex) => (
															<TreasureConvoyCard
																fleet={fleet}
																inGeneratingConvoysSection={section.generatingConvoys}
																onFocus={() => setFocusedConvoyCard(fleet.cityID)}
																autoFocus={shouldAutoFocusConvoyCard(
																	fleet.cityID,
																	index(),
																	subIndex(),
																)}
															/>
														)}
													</For>
												</div>
											}
										>
											<div class="flex flex-col flex-wrap text-wrap text-center items-center justify-center my-4">
												<div class="text-secondary uppercase">
													<L10n.Compose text="LOC_COMMERCE_TREASURE_FLEETS_EMPTY_TITLE" />
												</div>
												<Icon
													class="bg-center bg-contain bg-no-repeat w-16 h-4"
													name="url(popup_middle_decor)"
												/>
												<L10n.Compose text="LOC_COMMERCE_TREASURE_FLEETS_EMPTY_DESCRIPTION" />
											</div>
										</Show>
									</CollapsibleContainer>
								)}
							</For>
						</div>
					</ScrollArea>
				</GamepadTrayItemProvider>
			</CommerceScreenBaseTabContent>
		</SpatialSlot>
	);
};
//#endregion
